const pipe = (...fns) => (x) => fns.reduce((v, f) => f(v), x);

const addToken = (ctx) => ({ ...ctx, auth: true });
const logAccess = (ctx) => { console.log('Accessing'); return ctx; };
const fetchUser = (ctx) => { 
  if (!ctx.auth) throw new Error('Unauthorized');
  return { ...ctx, user: 'Admin' };
};

const processRequest = pipe(logAccess, addToken, fetchUser);

// Execution
processRequest({ url: '/api' });

